{"content":"import { createClient } from '@supabase/supabase-js';

const config = window.__APP_CONFIG__ || {};
if (!config.supabaseUrl || !config.supabaseAnonKey) {
  throw new Error('Supabase is not configured. The server must provide /config.js with a public URL and anon key.');
}

export const supabase = createClient(config.supabaseUrl, config.supabaseAnonKey, {
  auth: {
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true
  }
});

let accessToken = null;
let currentUser = null;

supabase.auth.getSession().then(({ data }) => {
  accessToken = data.session?.access_token || null;
  currentUser = data.session?.user || null;
});

supabase.auth.onAuthStateChange((_event, session) => {
  accessToken = session?.access_token || null;
  currentUser = session?.user || null;
});

export function getAccessToken() {
  return accessToken;
}

export function getCurrentUser() {
  return currentUser;
}

if (!window.AppAuth) {
  window.AppAuth = {};
}
window.AppAuth.getAccessToken = getAccessToken;
window.AppAuth.getCurrentUser = getCurrentUser;
window.AppAuth.signOut = () => supabase.auth.signOut();
