    border-radius: 50%;
    color: #fff;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    font-size: 0.85rem;
}

.sidebar-actions {
    display: flex;
    gap: 0.8rem;
    align-items: center;
    padding: 0 0.4rem;
    font-size: 0.9rem;
}

.sidebar-actions a {
