}

#signout-btn {
    background: transparent;
    border: 1px solid var(--border-warm);
    border-radius: 8px;
    color: var(--text-warm);
    cursor: pointer;
    padding: 0.35rem 0.7rem;
    font-size: 0.85rem;
}

#signout-btn:hover {
    border-color: var(--primary);
    color: var(--primary);
}

#content {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

#content header {
    position: static;
}

#topbar {
    display: flex;
    align-items: center;
    gap: 0.8rem;
    padding: 0.7rem 1.5rem;
    border-bottom: 1px solid var(--border-warm);
}

#menu-btn {
    display: none;
    background: transparent;
    border: 1px solid var(--border-warm);
    border-radius: 8px;
    color: var(--light);
    cursor: pointer;
    padding: 0.35rem 0.6rem;
}

#view-root {
    flex: 1;
    max-width: 1200px;
    width: 100%;
    margin: 0 auto;
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
}

#view-root > section {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: calc(100vh - 12rem);
}

#rail {
    background: var(--header-bg);
    border-left: 1px solid var(--border-warm);
    padding: 1.2rem 1rem;
    position: sticky;
    top: 0;
    height: 100vh;
    overflow-y: auto;
}

#rail[hidden] {
    display: none;
}

/* Views */
.view-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    margin-bottom: 1.2rem;
}

.view-head h1 {
    font-size: 1.5rem;
}

.empty-state {
    background: var(--message-bg);
    border: 1px solid var(--border-warm);
    border-radius: var(--radius);
    padding: 2rem;
    text-align: center;
    color: var(--text-warm);
}

.muted {
    color: var(--text-warm);
    font-size: 0.9rem;
}

.chat-toolbar {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.chat-toolbar .btn {
    background: var(--bg-warm);
    border: 1px solid var(--border-warm);
    border-radius: 8px;
    color: var(--light);
    cursor: pointer;
    font-size: 0.85rem;
    padding: 0.4rem 0.75rem;
}

.chat-toolbar .btn:hover {
    border-color: var(--primary);
    color: var(--primary);
}

.chat-toolbar .spacer {
    flex: 1;
}

#toast-root {
    position: fixed;
    bottom: 1.2rem;
    right: 1.2rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    z-index: 200;
}

.toast {
    background: #1e293b;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 8px;
    color: #fff;
    font-size: 0.9rem;
    padding: 0.7rem 1rem;
    max-width: 320px;
}

@media (max-width: 1200px) {
    #shell {
        grid-template-columns: 264px minmax(0, 1fr);
    }
    #rail {
        display: none;
    }
}

@media (max-width: 820px) {
    #shell {
        grid-template-columns: minmax(0, 1fr);
    }
    #sidebar {
        position: fixed;
        left: 0;
        top: 0;
        bottom: 0;
        width: 264px;
        z-index: 100;
        transform: translateX(-100%);
        transition: transform 0.25s ease;
    }
    body.nav-open #sidebar {
        transform: translateX(0);
    }
    #menu-btn,
    #menu-close {
        display: inline-flex;
    }
    #view-root {
        padding: 1rem;
    }
}

@media (prefers-reduced-motion: reduce) {
    #sidebar {
        transition: none;
    }
}
